// Package otp implements phone verification. Service owns the parts that
// stay the same no matter who's actually generating/checking the code
// (request cooldown, attempt limiting, session storage in Redis); the
// Provider interface (see provider.go) owns the code itself — either
// generated by us (SelfGenProvider, over any sms.Sender) or by a vendor's
// managed OTP product (e.g. SMSMKTOTPProvider). Swapping is a one-line
// change in main.go either way.
package otp

import (
	"context"
	"errors"
	"fmt"
	"log"
	"time"

	"github.com/redis/go-redis/v9"
)

const (
	sessionTTL        = 5 * time.Minute
	requestCooldown   = 60 * time.Second
	maxAttempts       = 5
	sessionKeyPrefix  = "otp:session:"
	cooldownKeyPrefix = "otp:cooldown:"
	attemptsKeyPrefix = "otp:attempts:"
)

var (
	ErrCooldown        = errors.New("otp: request too soon, wait before retrying")
	ErrNotFound        = errors.New("otp: no pending code for this phone (expired or never requested)")
	ErrTooManyAttempts = errors.New("otp: too many failed attempts, request a new code")
	ErrIncorrectCode   = errors.New("otp: incorrect code")
)

type Service struct {
	redis    *redis.Client
	provider Provider
}

func NewService(redisClient *redis.Client, provider Provider) *Service {
	return &Service{redis: redisClient, provider: provider}
}

// Request asks the active Provider to generate/deliver an OTP, then
// stores the session data it returns in Redis. Returns ErrCooldown if
// called again for the same phone within requestCooldown — this is the
// "max 1 request/60s per phone" abuse guard; pair it with a daily-count
// limit at the HTTP handler/middleware layer.
func (s *Service) Request(ctx context.Context, phone string) error {
	cooldownKey := cooldownKeyPrefix + phone
	set, err := s.redis.SetNX(ctx, cooldownKey, "1", requestCooldown).Result()
	if err != nil {
		return fmt.Errorf("otp: cooldown check: %w", err)
	}
	if !set {
		return ErrCooldown
	}

	session, err := s.provider.Send(ctx, phone)
	if err != nil {
		log.Printf("otp: provider send failed for %s: %v", phone, err)
		// Roll back the cooldown too — a failed send shouldn't block a
		// retry for a full 60s.
		s.redis.Del(ctx, cooldownKey)
		return fmt.Errorf("otp: send: %w", err)
	}

	sessionKey := sessionKeyPrefix + phone
	if err := s.redis.Set(ctx, sessionKey, session, sessionTTL).Err(); err != nil {
		return fmt.Errorf("otp: store session: %w", err)
	}
	s.redis.Del(ctx, attemptsKeyPrefix+phone)

	return nil
}

// Verify checks a user-submitted code against the session stored for this
// phone, via the active Provider. On success, the session is deleted
// (single use). On failure, it increments an attempt counter and returns
// ErrTooManyAttempts once maxAttempts is hit (guards the 6-digit /
// 1M-combination space against brute force).
func (s *Service) Verify(ctx context.Context, phone, submittedCode string) error {
	attemptsKey := attemptsKeyPrefix + phone
	attempts, err := s.redis.Incr(ctx, attemptsKey).Result()
	if err != nil {
		return fmt.Errorf("otp: attempts check: %w", err)
	}
	if attempts == 1 {
		s.redis.Expire(ctx, attemptsKey, sessionTTL)
	}
	if attempts > maxAttempts {
		return ErrTooManyAttempts
	}

	sessionKey := sessionKeyPrefix + phone
	session, err := s.redis.Get(ctx, sessionKey).Result()
	if errors.Is(err, redis.Nil) {
		return ErrNotFound
	}
	if err != nil {
		return fmt.Errorf("otp: fetch session: %w", err)
	}

	ok, err := s.provider.Validate(ctx, session, submittedCode)
	if err != nil {
		return fmt.Errorf("otp: validate: %w", err)
	}
	if !ok {
		return ErrIncorrectCode
	}

	s.redis.Del(ctx, sessionKey, attemptsKey)
	return nil
}
